	@Test
	void exactNegativeKernelsPreserveOuterBagMultiplicityAndSampledZeroStatus() {
		FrontierLayout layout = FrontierLayout.of("x");
		FrontierMaskStrata masks = FrontierMaskStrata.of(layout, 1, new long[] { 1L });
		FrontierStateKey exactParentKey = key(0b001L, masks);
		FrontierStateKey exactChildKey = key(0b011L, masks);
		FrontierStateKey sampledParentKey = key(0b100L, masks);
		FrontierStateKey sampledChildKey = key(0b110L, masks);

		try (FrontierStateArena arena = new FrontierStateArena(256 * 1024L)) {
			arena.declareCanonicalStates(exactParentKey, exactChildKey, sampledParentKey, sampledChildKey);

			FrontierPayloadWriter exactWriter = arena.newPayloadWriter(
					exactParentKey, new int[] { 2 }, new int[] { 0 });
			exactWriter.putExact(0, 0, 3.0d, new long[] { 11L }, 0);
			exactWriter.putExact(0, 1, 4.0d, new long[] { 12L }, 0);
			EvidenceStateRef exactParent = arena.internPayload(
					exactParentKey,
					EvidenceStateSummary.exact(7.0d),
					FrontierStateOperation.EXACT_LEAF,
					null,
					null,
					1,
					exactWriter);

			EvidenceStateRef exactNegative = FrontierLinearTransforms.resolveProjectedOuterKernel(
					arena,
					exactParent,
					exactChildKey,
					2,
					FrontierOuterKernel.NOT_EXISTS,
					(payload, exact, stratum, index) -> payload.exactTermId(stratum, index, 0) == 11L ? 0L : 2L,
					2,
					1.0d);
			assertEquals(EvidenceGuarantee.DATABASE_EXACT, exactNegative.summary().guarantee());
			assertEquals(3.0d, exactNegative.summary().pointRows());
			try (FrontierPayloadLease payload = arena.openPayload(exactNegative)) {
				assertEquals(1, payload.exactCount(0));
				assertEquals(3.0d, payload.exactWeight(0, 0));
				assertEquals(11L, payload.exactTermId(0, 0, 0));
			}

			FrontierPayloadWriter sampledWriter = arena.newPayloadWriter(
					sampledParentKey, new int[] { 0 }, new int[] { 1 });
			sampledWriter.putResidual(0, 0, 5.0d, new long[] { 11L }, 0);
			EvidenceStateRef sampledParent = arena.internPayload(
					sampledParentKey,
					unbiased(5.0d, 10.0d, 1.0d, 1.0d),
					FrontierStateOperation.COORDINATED_STAR,
					null,
					null,
					3,
					sampledWriter);

			EvidenceStateRef sampledZero = FrontierLinearTransforms.resolveProjectedOuterKernel(
					arena,
					sampledParent,
					sampledChildKey,
					4,
					FrontierOuterKernel.NOT_EXISTS,
					(payload, exact, stratum, index) -> 1L,
					1,
					1.0d);
			assertEquals(EvidenceGuarantee.MEASURE_UNBIASED, sampledZero.summary().guarantee());
			assertEquals(EvidenceZeroStatus.ESTIMATED_ZERO, sampledZero.summary().zeroStatus());
			assertEquals(0.0d, sampledZero.summary().pointRows());
			assertEquals(10.0d, sampledZero.summary().certifiedUpperBound());
			try (FrontierPayloadLease payload = arena.openPayload(sampledZero)) {
				assertEquals(0, payload.exactCount(0));
				assertEquals(0, payload.residualCount(0));
			}
			assertTrue(arena.temporaryReservedBytes() == 0L);
		}
	}

	@Test
	void exactOuterTupleExpansionPreservesMasksAndCoalescesBagDuplicates() {
		FrontierLayout inputLayout = FrontierLayout.of("x");
		FrontierMaskStrata inputMasks = FrontierMaskStrata.of(inputLayout, 1, new long[] { 1L });
		FrontierLayout outputLayout = FrontierLayout.of("x", "y");
		FrontierMaskStrata outputMasks = FrontierMaskStrata.of(outputLayout, 2, new long[] { 1L, 3L });
		FrontierStateKey inputKey = key(0b0001L, inputMasks);
		FrontierStateKey outputKey = key(0b0011L, outputMasks);

		try (FrontierStateArena arena = new FrontierStateArena(256 * 1024L)) {
			arena.declareCanonicalStates(inputKey, outputKey);
			FrontierPayloadWriter inputWriter = arena.newPayloadWriter(
					inputKey, new int[] { 2 }, new int[] { 0 });
			inputWriter.putExact(0, 0, 2.0d, new long[] { 11L }, 0);
			inputWriter.putExact(0, 1, 3.0d, new long[] { 12L }, 0);
			EvidenceStateRef input = arena.internPayload(
					inputKey,
					EvidenceStateSummary.exact(5.0d),
					FrontierStateOperation.EXACT_LEAF,
					null,
					null,
					30,
					inputWriter);
			int[] expansionCalls = { 0 };

			EvidenceStateRef output = FrontierLinearTransforms.expandOuterMappings(
					arena,
					input,
					outputKey,
					31,
					(payload, exact, stratum, index, emitter) -> {
						expansionCalls[0]++;
						long x = payload.exactTermId(stratum, index, 0);
						if (x == 11L) {
							emitter.emit(1, new long[] { x, 21L });
							emitter.emit(1, new long[] { x, 21L });
						} else {
							emitter.emit(0, new long[] { x, 0L });
						}
					},
					3);

			assertEquals(EvidenceGuarantee.DATABASE_EXACT, output.summary().guarantee());
			assertEquals(7.0d, output.summary().pointRows());
			assertEquals(2, expansionCalls[0], "Every outer mapping should be expanded exactly once");
			try (FrontierPayloadLease payload = arena.openPayload(output)) {
				assertEquals(1, payload.exactCount(0));
				assertEquals(12L, payload.exactTermId(0, 0, 0));
				assertEquals(3.0d, payload.exactWeight(0, 0));
				assertEquals(1, payload.exactCount(1));
				assertEquals(11L, payload.exactTermId(1, 0, 0));
				assertEquals(21L, payload.exactTermId(1, 0, 1));
				assertEquals(4.0d, payload.exactWeight(1, 0));
			}
			assertEquals(0L, arena.temporaryReservedBytes());
		}
	}

	@Test
	void exactOuterExpansionStratifiesFanoutWithinRefinementBudget() {
		FrontierLayout inputLayout = FrontierLayout.of("x");
		FrontierMaskStrata inputMasks = FrontierMaskStrata.of(inputLayout, 1, new long[] { 1L });
		FrontierLayout outputLayout = FrontierLayout.of("x", "y");
		FrontierMaskStrata outputMasks = FrontierMaskStrata.of(outputLayout, 1, new long[] { 3L });
		FrontierStateKey inputKey = key(0b0001L, inputMasks);
		FrontierStateKey outputKey = key(0b0011L, outputMasks);

		try (FrontierStateArena arena = new FrontierStateArena(256 * 1024L)) {
			arena.declareCanonicalStates(inputKey, outputKey);
			FrontierPayloadWriter inputWriter = arena.newPayloadWriter(
					inputKey, new int[] { 2 }, new int[] { 0 });
			inputWriter.putExact(0, 0, 1.0d, new long[] { 11L }, 0);
			inputWriter.putExact(0, 1, 1.0d, new long[] { 12L }, 0);
			EvidenceStateRef input = arena.internPayload(
					inputKey,
					EvidenceStateSummary.exact(2.0d),
					FrontierStateOperation.EXACT_LEAF,
					null,
					null,
					32,
					inputWriter);
			int[] emissionAttempts = { 0 };

			EvidenceStateRef output = FrontierLinearTransforms.expandOuterMappings(
					arena,
					input,
					outputKey,
					33,
					(payload, exact, stratum, index, emitter) -> {
						for (int value = 0; value < 100; value++) {
							emissionAttempts[0]++;
							long x = payload.exactTermId(stratum, index, 0);
							emitter.emit(0, new long[] { x, 100L + value });
						}
					},
					4);

			assertEquals(EvidenceGuarantee.MEASURE_UNBIASED, output.summary().guarantee());
			assertEquals(200.0d, output.summary().pointRows(), 1e-12);
			assertEquals(200.0d, output.summary().certifiedUpperBound(), 1e-12);
			assertEquals(200, emissionAttempts[0], "Exact probes must finish counting their bounded output measure");
			try (FrontierPayloadLease payload = arena.openPayload(output)) {
				assertEquals(0, payload.exactCount(0));
				assertEquals(4, payload.residualCount(0));
				boolean retainedFirstOuter = false;
				boolean retainedSecondOuter = false;
				double retainedMass = 0.0d;
				for (int index = 0; index < payload.residualCount(0); index++) {
					retainedFirstOuter |= payload.residualTermId(0, index, 0) == 11L;
					retainedSecondOuter |= payload.residualTermId(0, index, 0) == 12L;
					retainedMass += payload.residualWeight(0, index);
				}
				assertTrue(retainedFirstOuter, "Stratification must retain the first exact outer mapping");
				assertTrue(retainedSecondOuter, "Stratification must retain the second exact outer mapping");
				assertEquals(200.0d, retainedMass, 1e-12);
			}
			assertEquals(0L, arena.temporaryReservedBytes());
		}
	}

